@preconcurrency import SwiftNumber
@preconcurrency import Eth
import Foundation

public enum CometSupplyActions {
    public static let creationCode: Hex = ""
    public static let runtimeCode: Hex = ""

    public static let InvalidInputError = ABI.Function(
            name: "InvalidInput",
            inputs: []
    )


    public enum RevertReason : Equatable, Error {
        case invalidInput
        case unknownRevert(String, String)
    }
    public static func rewrapError(_ error: ABI.Function, value: ABI.Value) -> RevertReason {
        switch (error, value) {
        case (InvalidInputError, _):
            return .invalidInput
        case let (e, v):
            return .unknownRevert(e.name, String(describing: v))
        }
    }
    public static let errors: [ABI.Function] = [InvalidInputError]
    public static let functions: [ABI.Function] = [supplyFn, supplyFromFn, supplyMultipleAssetsFn, supplyToFn]
    public static let supplyFn = ABI.Function(
            name: "supply",
            inputs: [.address, .address, .uint256, .bool],
            outputs: []
    )

    public static func supply(comet: EthAddress, asset: EthAddress, amount: Number, cappedMax: Bool, withFunctions ffis: EVM.FFIMap = [:]) throws -> Result<(), RevertReason> {
            do {
                let query = try supplyFn.encoded(with: [.address(comet), .address(asset), .uint256(amount), .bool(cappedMax)])
                let result = try EVM.runQuery(bytecode: runtimeCode, query: query, withErrors: errors, withFunctions: ffis)
                let decoded = try supplyFn.decode(output: result)

                switch decoded {
                case  .tuple0:
                    return .success(())
                default:
                    throw ABI.DecodeError.mismatchedType(decoded.schema, supplyFn.outputTuple)
                }
            } catch let EVM.QueryError.error(e, v) {
                return .failure(rewrapError(e, value: v))
            }
    }


    public static func supplyDecode(input: Hex) throws -> (EthAddress, EthAddress, Number, Bool) {
        let decodedInput = try supplyFn.decodeInput(input: input)
        switch decodedInput {
        case let .tuple4(.address(comet), .address(asset), .uint256(amount), .bool(cappedMax)):
            return  (comet, asset, amount, cappedMax)
        default:
            throw ABI.DecodeError.mismatchedType(decodedInput.schema, supplyFn.inputTuple)
        }
    }

    public static let supplyFromFn = ABI.Function(
            name: "supplyFrom",
            inputs: [.address, .address, .address, .address, .uint256, .bool],
            outputs: []
    )

    public static func supplyFrom(comet: EthAddress, from: EthAddress, to: EthAddress, asset: EthAddress, amount: Number, cappedMax: Bool, withFunctions ffis: EVM.FFIMap = [:]) throws -> Result<(), RevertReason> {
            do {
                let query = try supplyFromFn.encoded(with: [.address(comet), .address(from), .address(to), .address(asset), .uint256(amount), .bool(cappedMax)])
                let result = try EVM.runQuery(bytecode: runtimeCode, query: query, withErrors: errors, withFunctions: ffis)
                let decoded = try supplyFromFn.decode(output: result)

                switch decoded {
                case  .tuple0:
                    return .success(())
                default:
                    throw ABI.DecodeError.mismatchedType(decoded.schema, supplyFromFn.outputTuple)
                }
            } catch let EVM.QueryError.error(e, v) {
                return .failure(rewrapError(e, value: v))
            }
    }


    public static func supplyFromDecode(input: Hex) throws -> (EthAddress, EthAddress, EthAddress, EthAddress, Number, Bool) {
        let decodedInput = try supplyFromFn.decodeInput(input: input)
        switch decodedInput {
        case let .tuple6(.address(comet), .address(from), .address(to), .address(asset), .uint256(amount), .bool(cappedMax)):
            return  (comet, from, to, asset, amount, cappedMax)
        default:
            throw ABI.DecodeError.mismatchedType(decodedInput.schema, supplyFromFn.inputTuple)
        }
    }

    public static let supplyMultipleAssetsFn = ABI.Function(
            name: "supplyMultipleAssets",
            inputs: [.address, .array(.address), .array(.uint256), .array(.bool)],
            outputs: []
    )

    public static func supplyMultipleAssets(comet: EthAddress, assets: [EthAddress], amounts: [Number], cappedMaxes: [Bool], withFunctions ffis: EVM.FFIMap = [:]) throws -> Result<(), RevertReason> {
            do {
                let query = try supplyMultipleAssetsFn.encoded(with: [.address(comet), .array(.address, assets.map {
                                    .address($0)
                                }), .array(.uint256, amounts.map {
                                    .uint256($0)
                                }), .array(.bool, cappedMaxes.map {
                                    .bool($0)
                                })])
                let result = try EVM.runQuery(bytecode: runtimeCode, query: query, withErrors: errors, withFunctions: ffis)
                let decoded = try supplyMultipleAssetsFn.decode(output: result)

                switch decoded {
                case  .tuple0:
                    return .success(())
                default:
                    throw ABI.DecodeError.mismatchedType(decoded.schema, supplyMultipleAssetsFn.outputTuple)
                }
            } catch let EVM.QueryError.error(e, v) {
                return .failure(rewrapError(e, value: v))
            }
    }


    public static func supplyMultipleAssetsDecode(input: Hex) throws -> (EthAddress, [EthAddress], [Number], [Bool]) {
        let decodedInput = try supplyMultipleAssetsFn.decodeInput(input: input)
        switch decodedInput {
        case let .tuple4(.address(comet), .array(.address, assets), .array(.uint256, amounts), .array(.bool, cappedMaxes)):
            return  (comet, assets.map { $0.asEthAddress! }, amounts.map { $0.asNumber! }, cappedMaxes.map { $0.asBool! })
        default:
            throw ABI.DecodeError.mismatchedType(decodedInput.schema, supplyMultipleAssetsFn.inputTuple)
        }
    }

    public static let supplyToFn = ABI.Function(
            name: "supplyTo",
            inputs: [.address, .address, .address, .uint256, .bool],
            outputs: []
    )

    public static func supplyTo(comet: EthAddress, to: EthAddress, asset: EthAddress, amount: Number, cappedMax: Bool, withFunctions ffis: EVM.FFIMap = [:]) throws -> Result<(), RevertReason> {
            do {
                let query = try supplyToFn.encoded(with: [.address(comet), .address(to), .address(asset), .uint256(amount), .bool(cappedMax)])
                let result = try EVM.runQuery(bytecode: runtimeCode, query: query, withErrors: errors, withFunctions: ffis)
                let decoded = try supplyToFn.decode(output: result)

                switch decoded {
                case  .tuple0:
                    return .success(())
                default:
                    throw ABI.DecodeError.mismatchedType(decoded.schema, supplyToFn.outputTuple)
                }
            } catch let EVM.QueryError.error(e, v) {
                return .failure(rewrapError(e, value: v))
            }
    }


    public static func supplyToDecode(input: Hex) throws -> (EthAddress, EthAddress, EthAddress, Number, Bool) {
        let decodedInput = try supplyToFn.decodeInput(input: input)
        switch decodedInput {
        case let .tuple5(.address(comet), .address(to), .address(asset), .uint256(amount), .bool(cappedMax)):
            return  (comet, to, asset, amount, cappedMax)
        default:
            throw ABI.DecodeError.mismatchedType(decodedInput.schema, supplyToFn.inputTuple)
        }
    }

}